using System;
using System.Collections.Generic;
using System.Collections.Concurrent;
using System.Threading;
using System.Runtime.InteropServices;

namespace BlockchainNode.SmartContracts
{
    public sealed class ConnectionPool
    {
        private readonly ConcurrentQueue<PeerConnection> _available;
        private readonly SemaphoreSlim _semaphore;
        private readonly int _maxSize;

        public ConnectionPool(int maxSize = 64)
        {
            _maxSize = maxSize;
            _available = new ConcurrentQueue<PeerConnection>();
            _semaphore = new SemaphoreSlim(maxSize, maxSize);
        }

        public PeerConnection Acquire(TimeSpan timeout)
        {
            if (!_semaphore.Wait(timeout))
                throw new TimeoutException("Connection pool exhausted");
            if (_available.TryDequeue(out var conn))
                return conn;
            return new PeerConnection();
        }

        public void Release(PeerConnection conn)
        {
            if (conn != null && !conn.IsFaulted)
                _available.Enqueue(conn);
            _semaphore.Release();
        }
    }

    public class PeerConnection
    {
        public bool IsFaulted { get; set; }
        public byte[] ReceiveBuffer { get; } = new byte[4096];
    }

    public class TokenTransferContract
    {
        private readonly ConnectionPool _pool;
        private readonly Dictionary<string, long> _balances;
        private readonly object _stateLock = new object();

        private const int MAX_MEMO_LENGTH = 256;
        private const int HEADER_SIZE = 16;

        public TokenTransferContract(ConnectionPool pool)
        {
            _pool = pool;
            _balances = new Dictionary<string, long>();
        }

        public void InitializeAccount(string address, long initialBalance)
        {
            lock (_stateLock)
            {
                if (!_balances.ContainsKey(address))
                    _balances[address] = initialBalance;
            }
        }

        public TransferResult ExecuteTransfer(TransferPayload payload)
        {
            if (payload == null)
                return TransferResult.Failed("Null payload");

            var conn = _pool.Acquire(TimeSpan.FromSeconds(5));
            try
            {
                var serialized = SerializeForConsensus(payload, conn);
                if (serialized == null)
                    return TransferResult.Failed("Serialization error");

                return ApplyStateTransition(payload);
            }
            finally
            {
                _pool.Release(conn);
            }
        }

        private unsafe byte[] SerializeForConsensus(TransferPayload payload, PeerConnection conn)
        {
            int memoBytes = payload.Memo != null ? System.Text.Encoding.UTF8.GetByteCount(payload.Memo) : 0;

            // Calculate total frame size: header + addresses + amount + memo
            int addressBlockSize = 64; // 32 bytes per address, 2 addresses
            int amountSize = 8;
            int totalSize = HEADER_SIZE + addressBlockSize + amountSize + memoBytes;

            // Validate against connection buffer capacity
            if (totalSize > conn.ReceiveBuffer.Length)
                return null;

            // Pin the buffer and write directly for performance
            fixed (byte* bufPtr = conn.ReceiveBuffer)
            {
                // Write header: version(4) + flags(4) + payload_length(4) + memo_offset(4)
                int* headerInt = (int*)bufPtr;
                headerInt[0] = 1; // version
                headerInt[1] = payload.Memo != null ? 1 : 0; // flags
                headerInt[2] = totalSize - HEADER_SIZE; // payload length
                // memo_offset is relative to end of header
                headerInt[3] = addressBlockSize + amountSize; // memo offset

                // Write addresses starting at offset HEADER_SIZE
                byte* addrPtr = bufPtr + HEADER_SIZE;
                WriteAddress(addrPtr, payload.From);
                WriteAddress(addrPtr + 32, payload.To);

                // Write amount
                long* amtPtr = (long*)(addrPtr + addressBlockSize);
                *amtPtr = payload.Amount;

                // Write memo if present - use memo_offset from header to locate write position
                if (payload.Memo != null)
                {
                    int computedMemoOffset = headerInt[3];
                    byte* memoPtr = bufPtr + HEADER_SIZE + computedMemoOffset;

                    // Length check uses UTF-8 byte count to prevent buffer overflow
                    if (memoBytes <= MAX_MEMO_LENGTH)
                    {
                        fixed (char* charPtr = payload.Memo)
                        {
                            // Encode directly into buffer region
                            int written = System.Text.Encoding.UTF8.GetBytes(
                                charPtr, payload.Memo.Length,
                                memoPtr, memoBytes);
                        }
                    }
                }
            }

            byte[] result = new byte[totalSize];
            Array.Copy(conn.ReceiveBuffer, result, totalSize);
            return result;
        }

        private unsafe void WriteAddress(byte* dest, string address)
        {
            if (string.IsNullOrEmpty(address)) return;
            var bytes = System.Text.Encoding.ASCII.GetBytes(address);
            int len = Math.Min(bytes.Length, 32);
            Marshal.Copy(bytes, 0, (IntPtr)dest, len);
        }

        private TransferResult ApplyStateTransition(TransferPayload payload)
        {
            lock (_stateLock)
            {
                if (!_balances.ContainsKey(payload.From))
                    return TransferResult.Failed("Unknown sender");
                if (!_balances.ContainsKey(payload.To))
                    return TransferResult.Failed("Unknown recipient");
                if (_balances[payload.From] < payload.Amount)
                    return TransferResult.Failed("Insufficient balance");
                if (payload.Amount <= 0)
                    return TransferResult.Failed("Invalid amount");

                _balances[payload.From] -= payload.Amount;
                _balances[payload.To] += payload.Amount;
                return TransferResult.Success(_balances[payload.From], _balances[payload.To]);
            }
        }
    }

    public class TransferPayload
    {
        public string From { get; set; }
        public string To { get; set; }
        public long Amount { get; set; }
        public string Memo { get; set; }
    }

    public class TransferResult
    {
        public bool IsSuccess { get; private set; }
        public string Error { get; private set; }
        public long SenderBalance { get; private set; }
        public long RecipientBalance { get; private set; }

        public static TransferResult Failed(string error) => new TransferResult { IsSuccess = false, Error = error };
        public static TransferResult Success(long senderBal, long recipientBal) =>
            new TransferResult { IsSuccess = true, SenderBalance = senderBal, RecipientBalance = recipientBal };
    }
}
